INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137662, 'spa', 'Semana, período de siete días', 'Semana, período de siete días. Unidad temporal básica en hebreo derivada de la raíz ''siete'', anclada en el ritmo de la creación. Se usa para la semana nupcial en Génesis 29:27-28, el período de purificación en Levítico 12:5 y el conteo hacia la Fiesta de las Semanas en Deuteronomio 16:9. En el uso profético-apocalíptico de Daniel, la unidad se expande a héptadas de siete años (Dan 9:24-27, 10:2-3), donde ''semanas de días'' especifica semanas literales por contraste.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137664, 'spa', 'Fiesta de las Semanas (Shavuot)', 'Fiesta de las Semanas (Shavuot). Fiesta de peregrinación celebrada siete semanas después de la ofrenda de la primera gavilla, que marca la cosecha del trigo (Núm 28:26; Deut 16:10, 16). Es una de las tres peregrinaciones anuales junto con la Pascua y los Tabernáculos. Las traducciones multilingües tienden a transliterar o capitalizar (''Semanas'') en lugar de traducir, reflejando su carácter de nombre propio como festividad establecida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137675, 'spa', 'El sentido dominante (29x)', 'El sentido dominante (29x): un voto solemne o compromiso jurado que invoca el testimonio divino. Las traducciones lo tratan uniformemente como una promesa vinculante. Cubre juramentos de amistad (2 Sam 21:7), pactos de alianza (Gn 26:3), juramentos de inocencia (Éx 22:11) y votos junto con נדר (Nm 30:3). La frase שְׁבֻעַת יהוה marca los juramentos pronunciados ante el Señor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137683, 'spa', 'Un sentido raro pero distinto (1x en Isa 65', 'Un sentido raro pero distinto (1x en Isa 65:15): la fórmula de juramento adquiere carácter de maldición o imprecación. Dios declara que los nombres de los desobedientes quedarán como שְׁבוּעָה — una fórmula de maldición que los escogidos invocarán. Esto revela el desplazamiento del juramento promisorio a la maldición autoimprecatoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137691, 'spa', 'El estado de cautividad o exilio, ser llevado y retenido en tierra extranjera', 'El estado de cautividad o exilio, ser llevado y retenido en tierra extranjera. La palabra aparece en las grandes promesas de restauracion: Deuteronomio 30:3 (''el SENOR tu Dios restaurara tu cautividad''), Salmo 126:4 (''restaura nuestra cautividad como arroyos en el Neguev'') y los oraculos profeticos donde Dios promete revertir el destierro de su pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137696, 'spa', 'La fortuna o condicion general de un pueblo, extendiendose mas alla de la cautiv', 'La fortuna o condicion general de un pueblo, extendiendose mas alla de la cautividad literal para abarcar el bienestar o la afliccion en sentido amplio. Este sentido emerge claramente en Job 42:10, donde Dios restaura la ''fortuna'' de Job, quien nunca fue exiliado sino afligido con sufrimiento. Los Salmos 14:7 y 53:6 oran por que Dios restaure la suerte de su pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137716, 'spa', 'Calmar/aquietar', 'Dos casos describen a Dios aquietando el mar (Salmos 65:7 y 89:9), usando imágenes paralelas de soberanía divina sobre aguas caóticas. Proverbios 29:11 cambia a calmar el espíritu o temperamento propio. El español ''calmar'' y el francés ''calmer'' coinciden en todos los usos. Los contextos sálmicos conectan este poder de aquietar con la teología de la creación, donde Dios somete el caos primordial, mientras que Proverbios democratiza el concepto aplicándolo al autocontrol humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137717, 'spa', 'Alabar, loar', 'Piel: alabar, loar o ensalzar, dirigido predominantemente a Dios en contextos litúrgicos. El Salmo 117:1 llama a todas las naciones a «alabarle» (paralelo a הָלַל), el Salmo 63:3 declara que «los labios te alabarán», y el Salmo 145:4 promete que una generación «ensalzará» las obras de Dios ante la siguiente. En Eclesiastés adquiere un tono sapiencial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137720, 'spa', 'Gloriarse, jactarse', 'Hitpael reflexivo: gloriarse, jactarse o enorgullecerse de algo, con la preposición בְּ marcando el objeto. En el Salmo 106:47 (= 1 Cr 16:35), la comunidad pide ser reunida «para gloriarnos en tu santo nombre». La Septuaginta lo traduce con (ἐγ)καυχᾶσθαι, «jactarse», confirmando el carácter reflexivo frente a la alabanza exterior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137724, 'spa', 'Alabar, glorificar', 'Alabar o loar, dirigiendo palabras de glorificación hacia una deidad. Daniel alaba al Dios del cielo por la sabiduría revelada (Dn 2:23) y Nabucodonosor al Altísimo tras su restauración (Dn 4:34, 37). El mismo verbo acusa a Belsasar de alabar ídolos inertes (Dn 5:4, 23), agudizando el contraste entre adoración verdadera y falsa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137726, 'spa', 'tribu, división tribal', 'Tribu o división tribal de Israel: el sentido más frecuente con diferencia — una de las unidades sociopolíticas descendientes de los hijos de Jacob. Génesis 49:28 concluye las bendiciones tribales con «todas estas son las doce tribus (שִׁבְטֵי) de Israel,» y la palabra aparece constantemente en Números, Josué y Jueces para la asignación y gobierno de los territorios tribales. El árabe سِبْط es cognado directo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137728, 'spa', 'vara, bastón, palo', 'Vara, bastón o palo (objeto físico): un instrumento concreto usado para golpear, disciplinar, pastorear o como arma. Éxodo 21:20 legisla el caso de un amo que golpea a un esclavo «con una vara,» y Proverbios 22:15 prescribe la «vara de la disciplina» para el corazón del niño. En 2 Samuel 23:21 Benaía arrebata un bastón a un guerrero egipcio — שֵׁבֶט como arma improvisada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137733, 'spa', 'cetro, bastón de mando', 'Cetro o bastón de autoridad: la vara elevada a símbolo de poder real o gubernativo. Génesis 49:10 profetiza que «no será quitado el cetro de Judá,» y Números 24:17 contempla «un cetro que se levantará de Israel.» Salmo 45:6 celebra el «cetro de justicia» del rey. La transición del cayado del pastor al cetro del soberano es natural: el mismo palo que guía ovejas se convierte en insignia de reino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137762, 'spa', 'dardo, lanza arrojadiza', 'Dardo o lanza corta (arma arrojadiza): aparición única en 2 Samuel 18:14 donde Joab toma tres שְׁבָטִים en su mano y los clava en el corazón de Absalón colgado del encina. El objeto aquí no es un bastón de caminar ni un símbolo de autoridad, sino un proyectil punzante. El español dardos, el francés darts y el alemán concuerdan en el sentido de arma arrojadiza, claramente diferenciado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137788, 'spa', 'La condicion abstracta de estar en cautividad o vivir en exilio', 'La condicion abstracta de estar en cautividad o vivir en exilio. El hebreo lo empareja con verbos de movimiento: הָלַךְ בַּשְּׁבִי ''fue al cautiverio'' (Am 9:4; Nah 3:10) y preposiciones locativas. Esdras 2:1 usa el constructo בְּנֵי שְׁבִי para designar a los ''hijos de la cautividad'', tratando el exilio como una identidad comunitaria definidora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137791, 'spa', 'Referencia concreta a personas capturadas, ya sea colectiva o individualmente', 'Referencia concreta a personas capturadas, ya sea colectiva o individualmente. En Numeros 31:12, 19, 26 el termino designa prisioneros reales traidos de la batalla; en Exodo 12:29 describe al cautivo en la mazmorra del Faraon. Los sufijos posesivos como שֶׁבְיְךָ ''tus cautivos'' (Jue 5:12) y שִׁבְיוֹ ''sus cautivos'' (Dt 21:11) confirman la lectura personal y concreta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137814, 'spa', 'Cautivos (personas)', 'Los cautivos como colectivo concreto — el conjunto de personas tomadas prisioneras en guerra. Deuteronomio 21:11 habla de ver a una mujer ''entre los cautivos'' (בַּשִּׁבְיָה), y 2 Crónicas 28:5, 11, 13-15 describe un ''gran cautiverio'' de personas que deben ser devueltas. Deuteronomio 32:42 empareja a los cautivos (שִׁבְיָה) con los muertos (חָלָל), confirmando la referencia personal concreta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137815, 'spa', 'Cautiverio (estado)', 'Cautiverio como estado o condición abstracta — el estar sometido, la experiencia del exilio. Nehemías 3:36 (4:4 en versiones inglesas) habla de ''la tierra del cautiverio'', y 2 Crónicas 6:37-38 describe a los exiliados reflexionando sobre su situación ''en la tierra de su cautividad''. Jeremías 48:46 asigna este sentido abstracto a las hijas de Moab que van ''al cautiverio''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137822, 'spa', 'Senda/camino', 'Los tres usos abarcan la senda milagrosa de Dios a través del Mar Rojo (Salmo 77:19, apareciendo dos veces) y las sendas abandonadas de Israel (Jeremías 18:15). El español ''sendas'' y el francés ''sentier'' capturan el significado. El pasaje del Salmo usa ''Tu senda'' en paralelo con ''Tu camino'', creando imágenes sinónimas de intervención salvífica divina. Las ''sendas antiguas'' de Jeremías contrastan rutas divinamente ordenadas con innovaciones humanas desviadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137824, 'spa', 'séptimo (ordinal)', 'Numeral ordinal ''séptimo,'' siempre usado con artículo definido, que marca posición en una secuencia — de manera más prominente el séptimo día de la creación y el reposo sabático (Gn 2:2-3; Éx 20:10), el séptimo mes del calendario litúrgico con su concentración de festividades (Lv 23:24, 27, 34), y el séptimo año de liberación (Éx 21:2; 23:11). En español el séptimo, en francés le septième, en alemán der siebte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137831, 'spa', 'Enrejado en los pilares', 'Enrejado en los pilares. Enrejado ornamental o red de cuadrículas elaborada como decoración en los capiteles de los pilares del Templo. Catorce apariciones se concentran en los relatos de la construcción del Templo en 1 Reyes 7, 2 Reyes 25, 2 Crónicas 4 y Jeremías 52, donde los enrejados se describen junto a hileras de granadas sobre los pilares de bronce Jaquín y Boaz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137840, 'spa', 'Celosía de ventana', 'Celosía de ventana. Celosía o rejilla de ventana a través de la cual se mira o circula el aire — la contraparte doméstica del ornamento del Templo. Solo una aparición, en 2 Reyes 1:2, donde el rey Ocozías ''cayó por la celosía de su sala alta en Samaria y quedó herido''. La escena evoca habitaciones superiores antiguas con pantallas de tiras tejidas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137843, 'spa', 'Red o trampa', 'Red o trampa. Red, malla o trampa usada figuradamente para el atrapamiento. En Job 18:8, Bildad advierte que el impío ''es arrojado a una red por sus propios pies'', en paralelo con resheth (''red''), pach (''trampa'') y tsammim (''lazos'') en los versículos circundantes. El contexto metafórico confirma una extensión deliberada de la imagen de malla del ornamento arquitectónico al atrapamiento moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137846, 'spa', 'Corriente o torrente', 'Designa una corriente o torrente de agua. El Salmo 69:3 describe el ahogarse en una «corriente» (שִׁבֹּלֶת), e Isaías 27:12 habla de trillar «desde la corriente del Río» (מִשִּׁבֹּלֶת הַנָּהָר), refiriéndose al Éufrates. En Jueces 12:6 funciona como prueba dialectal: los galaaditas detectaban a los efraimitas que no podían pronunciar la שׁ inicial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137847, 'spa', 'Espiga de grano', 'Espiga de grano. La punta madura y cargada de semillas de los tallos de cereales como el trigo y la cebada. Once de las quince apariciones se concentran en la narración del sueño del faraón (Gn 41:5-27), donde el contraste entre espigas gruesas y delgadas impulsa la interpretación profética de José. También se encuentra en contextos de espigueo (Rt 2:2) y símiles de cosecha (Is 17:5; Job 24:24). Zacarías 4:12 extiende la imagen a las puntas de ramas de olivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137854, 'spa', 'Sibma (topónimo)', 'Ciudad moabita cerca de Hesbón, famosa por sus viñedos, que aparece en contextos históricos y proféticos. En Números 32:3 se usa la variante Sebán (שְׂבָם) al solicitar territorio transjordano; Números 32:38 y Josué 13:19 emplean la forma Sibma. Isaías 16:8-9 y Jeremías 48:32 lamentan la destrucción de sus viñedos en oráculos contra Moab.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137858, 'spa', 'Sebna (nombre propio)', 'El nombre personal Sebna, que designa a un funcionario histórico en la corte de Ezequías que sirvió primero como mayordomo de palacio y luego como secretario real. El oráculo de Isaías contra él (Is 22:15-19) ofrece una rara crítica profética de la ambición política de un individuo mencionado por nombre. En los relatos paralelos de la crisis asiria (2 R 18:18, 26, 37; 19:2; Is 36:3, 11, 22; 37:2) actúa junto a Eliaquim y Joa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137861, 'spa', 'Sebanías (nombre propio)', 'El nombre propio שְׁבַנְיָה/שְׁבַנְיָהוּ, que identifica a varios levitas y sacerdotes del Israel postexílico: un sacerdote que tocó la trompeta en la procesión del arca (1 Cr 15:24), levitas que dirigieron la oración comunitaria (Neh 9:4-5), y firmantes de la renovación del pacto (Neh 10:4, 10, 12). Las variantes de la Septuaginta reflejan inestabilidad fonológica en la transcripción griega.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137864, 'spa', 'Sentido intransitivo Qal y Nifal', 'Sentido intransitivo Qal y Nifal: estar satisfecho, lleno, tener suficiente. Es el significado dominante en 75 apariciones, abarcando fórmulas de bendición (Dt 6:11, «comerás y te saciarás»), literatura sapiencial (Pr 12:11) y promesas proféticas. Todos los glosarios multilingües apuntan a una plenitud satisfecha. A menudo se empareja con «comer» como su complemento natural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137875, 'spa', 'Sentido de connotación negativa', 'Sentido de connotación negativa: estar harto, empachado o hastiado en exceso de algo. En Is 1:11, Dios está «harto» de holocaustos — no complacido sino asqueado. Pr 25:16-17 advierte contra comer demasiada miel o visitar a un vecino con exceso, no sea que se «llene» de ti y te aborrezca. Aproximadamente diez apariciones muestran este giro oscuro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137878, 'spa', 'Sentido causativo Hifil y Piel', 'Sentido causativo Hifil y Piel: saciar a alguien, hacer que esté lleno, dar lo suficiente. Dios es frecuentemente el sujeto — «Te sacia de cosas buenas» (Sal 91:16), «Me llena» (Job 9:18). Esto traslada la agencia de quien está lleno a quien provee la plenitud. Dieciocho apariciones destacan al dador divino como origen de toda satisfacción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137938, 'spa', 'Abundancia, plenitud', 'Estado de abundancia o plenitud material, particularmente de alimentos y grano. Siete de las ocho apariciones se concentran en Génesis 41 (vv. 29, 30, 31, 34, 47, 53), describiendo los siete años de cosecha extraordinaria de Egipto en la narrativa de José. Proverbios 3:10 promete graneros rebosantes, y Eclesiastés 5:11 observa que la abundancia de bienes trae abundancia de consumidores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137942, 'spa', 'Saciedad, plenitud, abundancia', 'El estado de estar plenamente satisfecho, principalmente de alimento pero tambien metaforicamente de gozo. Literalmente describe comer hasta la saciedad: Israel recordando el pan de Egipto (Ex 16:3), la abundancia de la tierra prometida (Lv 25:19; 26:5) y Rut 2:18. El Salmo 16:11 extiende el significado al ambito espiritual con la plenitud de gozo en la presencia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137949, 'spa', 'Satisfecho, saciado, lleno', 'El estado de estar plenamente satisfecho o saciado, abarcando la hartura física de alimento (1 S 2:5; Pr 27:7), la abundancia figurada del favor divino (Dt 33:23, «lleno de la bendición de Jehová»), la conclusión pacífica de una vida larga expresada como «lleno de días» (Gn 25:8; 35:29; 1 Cr 29:28; Job 42:17), y en sentido negativo, el hartazgo de aflicción o vergüenza (Job 10:15; 14:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137957, 'spa', 'jurar, prestar juramento (Nifal)', 'Jurar o prestar juramento (forma Nifal). El sujeto se obliga mediante un juramento, ya sea promisorio (comprometiéndose a una acción futura, como en la celebración de pactos), asertorio (afirmando la verdad de una declaración) o imprecatorio (invocando a Dios como testigo con automaldición implícita). Es el sentido dominante con 154 apariciones. Dios jura a Abraham (Gn 24:7), David y Jonatán se juran lealtad mutua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137966, 'spa', 'hacer jurar, conjurar (Hifil)', 'Hacer jurar, conjurar o administrar un juramento (forma Hifil). El sujeto obliga o encarga solemnemente a otra parte que jure. Abraham hace jurar a su siervo (Gn 24:3), José hace jurar a los hijos de Israel que lleven sus huesos (Gn 50:25), y el estribillo del Cantar «os conjuro, hijas de Jerusalén» (Cnt 2:7; 3:5) emplea esta forma causativa. Unas 31 apariciones llevan este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137997, 'spa', 'ligado por juramentos', 'Forma participial rara o Qal pasivo que describe a quienes están «ligados por juramentos» o vinculados bajo juramento (Ez 21:23). Esta única aparición es textualmente difícil — la Septuaginta y la Siríaca la omiten, y algunos eruditos revocalizan para relacionarla con ''semanas'' en vez de ''juramentos.'' El pasaje describe el juramento roto de Sedequías a Nabucodonosor, y la expresión subraya la gravedad de la violación del pacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138023, 'spa', 'siete (número cardinal)', 'El número cardinal siete (393x), usado en todas las formas gramaticales — masculino, femenino, constructo, absoluto, con preposiciones prefijadas y en números compuestos como diecisiete o veintisiete. Las traducciones son perfectamente uniformes: inglés seven, español siete, francés sept, alemán sieben. Abarca edades genealógicas (Gn 5:7, 25, 31), estipulaciones rituales (siete días, siete corderos) y secuencias narrativas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138042, 'spa', 'siete veces (multiplicativo)', 'Siete usado como adverbio multiplicativo que significa ''siete veces'' (1x en Sal 119:164). El salmista declara: «Siete veces al día te alabo por tus justos juicios.» Aquí שֶׁבַע funciona adverbialmente para expresar acción repetida, y el número lleva connotaciones de plenitud y completud que impregnan su uso simbólico a lo largo de toda la Escritura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138049, 'spa', 'Seba (nombre propio)', 'El nombre personal שֶׁבַע, referido principalmente a Seba hijo de Bicri, un benjaminita que instigó una revuelta secesionista contra el rey David (2 S 20:1-22). Ocho de las nueve ocurrencias se concentran en 2 Samuel 20, narrando su rebelión, la persecución de Joab y su decapitación en Abel-bet-maaca. Un portador distinto del mismo nombre aparece entre los gaditas (1 Cr 5:13). La LXX lo transcribe como Σαβεε.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138053, 'spa', 'Saciedad, hartura', 'Estado de plena satisfacción, aplicado tanto a la saciedad física con alimentos como al exceso moral o espiritual. En sentido positivo aparece en promesas divinas de abundancia (Isa 23:18; Ezek 39:19). Isaías 55:2 lo emplea figuradamente para el verdadero sustento espiritual. Negativamente, la «hartura de pan» de Sodoma fomentó arrogancia (Ezek 16:49).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138059, 'spa', 'Siete (cardinal arameo)', 'Numeral cardinal arameo que significa «siete», empleado en las secciones arameas de Daniel y Esdras. En Daniel 3:19 aparece en la frase multiplicativa (חַד שִׁבְעָה עַל דִּי), indicando siete veces más de lo habitual. En Daniel 4:16, 23, 25 cuenta los «siete tiempos» de la locura de Nabucodonosor. En Esdras 7:14 designa a los siete consejeros del rey persa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138063, 'spa', 'El número cardinal setenta, empleado tanto para la enumeración precisa como para', 'El número cardinal setenta, empleado tanto para la enumeración precisa como para expresar totalidad o completitud de manera convencional. Los setenta ancianos en el Sinaí (Éx 24:1), los setenta años del exilio babilónico (Jer 25:11) y las setenta semanas de Daniel (Dn 9:24) ilustran su doble función como cifra literal y plenitud simbólica. Las traducciones multilingües — setenta, soixante-dix, siebzig — son uniformes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138068, 'spa', 'Séptuplo, siete veces', 'Numeral en forma dual que funciona como intensificador adverbial significando «siete veces» o «séptuplo», expresando plenitud de la acción divina y humana. En Génesis 4:15 aparece en el decreto de venganza séptupla contra quien mate a Caín. Lamec lo escala a «setenta y siete veces» (Gen 4:24). El Salmo 79:12 pide retribución séptupla contra los enemigos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138072, 'spa', 'Dejar, permitir quedar', 'Dejar en paz, permitir que permanezca sin perturbación. En la visión del árbol, el tocón debe ser ''dejado'' en la tierra, preservando el reino de Nabucodonosor durante el juicio (Dn 4:15, 23, 26). Darío ordena ''dejar en paz'' la reconstrucción del templo (Esd 6:7). El Hitpeel en Dn 2:44 describe un reino que ''no será dejado'' a otra nación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138074, 'spa', 'Esperar, aguardar', 'Piel: esperar, confiar o mirar expectantemente hacia alguien o algo, expresando confianza paciente. Aramaísmo cognado del arameo sebar («pensar, esperar»). Se usa de criaturas que esperan en Dios para su sustento (Sal 104:27; 145:15), de la esperanza personal en los mandamientos divinos (Sal 119:166), y de expectativas humanas frustradas (Est 9:1; Rut 1:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138081, 'spa', 'Qal: quebrar, destrozar', 'Sentido activo del Qal: quebrar o destrozar objetos físicos —vasijas, huesos, yugos, puertas, ídolos—. Los cántaros de Gedeón (Jue 7:20), la prohibición pascual de quebrar huesos (Éx 12:46) y el quebrantamiento del yugo como metáfora de liberación (Lv 26:13) ilustran este sentido fundacional. El árabe kasara corresponde directamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138083, 'spa', 'Nifal: ser quebrado', 'Pasivo del Nifal: ser quebrado o quedar destrozado, ya sea físicamente (una vasija rota, Lv 6:28) o metafóricamente (una nación quebrantada). El cuello de Elí se quiebra en su caída mortal (1 S 4:18); las naves son destrozadas por el viento del este (Ez 27:26). El árabe inkasara (forma VII pasiva) refleja con exactitud esta morfología.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138086, 'spa', 'Piel: hacer añicos', 'Piel intensivo: destrucción sistemática y total. El granizo que arrasa toda planta (Éx 9:25), Moisés destrozando las tablas (Éx 32:19) y el mandato de demoler los altares paganos (Éx 23:24). El árabe kassara (forma II intensiva) reproduce la intensificación morfológica. El Piel reiterado subraya la totalidad exigida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138092, 'spa', 'Nifal participio: quebrantado', 'Participio del Nifal empleado como adjetivo para un estado duradero de quebranto, especialmente del corazón y del espíritu humanos. El Salmo 34:18 declara a Dios cercano a los נִשְׁבְּרֵי-לֵב («quebrantados de corazón»), y el Salmo 51:17 une לֵב נִשְׁבָּר («corazón quebrantado») con רוּחַ נִדְכָּאָה («espíritu contrito»). La extensión metafórica de la fractura física a la emocional es universal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138104, 'spa', 'Hifil: hacer nacer', 'Uso singular del Hifil en Isaías 66:9, donde Dios pregunta si llevaría al punto de ruptura —las contracciones del parto— sin completar la entrega. La metáfora del alumbramiento reutiliza la raíz de rotura para la irrupción del parto, imagen vívida de renacimiento nacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138121, 'spa', 'Quebrantar en el lagar', 'En Lamentaciones 1:15 שָׁבַר aparece en el contexto de pisar el lagar, donde el Señor «quebranta» a la doncella de Judá. La imagen fusiona el aplastamiento físico con la personificación del dolor. El desplazamiento semántico hacia el sufrimiento corporal distingue este uso del quebrar ordinario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138159, 'spa', 'Estoy quebrantado', 'Jeremías 8:21 emplea un Nifal o Hofal en primera persona: «Estoy quebrantado», expresando la aflicción visceral del profeta ante la destrucción de su pueblo. El registro personal y emocional —castellano estoy quebrantado— marca este uso como una interiorización empática de la metáfora de la rotura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138185, 'spa', 'Saciar la sed', 'El Salmo 104:11 usa שָׁבַר de los asnos monteses que «quiebran» su sed en los arroyos del desierto, es decir, la sacian. Extensión semántica singular donde la rotura se aplica a un estado abstracto (la sed) que cesa. El uso puede reflejar un modismo paralelo al francés étancher la soif.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138194, 'spa', 'Comprar grano (Qal)', 'Comprar grano (Qal). Comprar o adquirir grano y provisiones alimenticias, sentido básico del Qal usado predominantemente en la narrativa de José durante la hambruna egipcia. Toda la tierra viene a José ''a comprar grano'' (Gén 41:57), Jacob envía a sus hijos a Egipto a comprar alimento (Gén 42:2-3), y los hermanos explican repetidamente que vinieron ''a comprar comida'' (Gén 42:7, 10; 43:2, 4, 20). Isaías 55:1 transforma el término comercial en una impactante metáfora teológica: ''Venid, comprad vino y leche sin dinero''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138196, 'spa', 'Vender grano (Hifil/causativo)', 'Vender grano (Hifil/causativo). Significado causativo del Hifil: ''vender grano'' o ''distribuir provisiones'', el acto complementario a comprar. José es llamado ''el que vende'' a toda la gente de la tierra (Gén 42:6), y Proverbios 11:26 contrasta al que retiene el grano con ''el que lo vende'', bendiciendo al vendedor generoso. Amós 8:5-6 usa ambos sentidos en la denuncia de mercaderes ansiosos por reanudar el comercio después del día de reposo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138206, 'spa', 'El sentido profetico dominante de destruccion catastrofica, ruina o colapso naci', 'El sentido profetico dominante de destruccion catastrofica, ruina o colapso nacional, concentrado en Isaias, Jeremias, Ezequiel y Proverbios. Es el שֶׁבֶר de los oraculos de juicio: el quebrantamiento de ciudades, reinos e individuos soberbios. Proverbios 16:18 lo cristalizo en un proverbio conocido mundialmente: ''antes del quebranto esta la soberbia.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138207, 'spa', 'Una herida o afliccion que requiere sanacion, caracterizada por su emparejamient', 'Una herida o afliccion que requiere sanacion, caracterizada por su emparejamiento con רָפָא (''sanar''). El gran lamento de Jeremias sobre Jerusalen produce la frase recurrente ''han curado la herida (שֶׁבֶר) de mi pueblo superficialmente'' (Jer 6:14; 8:11). Isaias 30:26 promete que Dios ''vendara la herida de su pueblo.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138213, 'spa', 'El sentido fisico concreto de rotura, fractura o quiebre de un objeto o parte de', 'El sentido fisico concreto de rotura, fractura o quiebre de un objeto o parte del cuerpo, en textos legales y sapienciales. Levitico 21:19 y 24:20 lo usan en la ley del talion: ''fractura por fractura'' (שֶׁבֶר תַּחַת שֶׁבֶר), donde la precision juridica exige un significado literal y anatomico. Isaias 30:14 compara el juicio con la rotura de un vaso de alfarero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138223, 'spa', 'La interpretacion de un sueno', 'La interpretacion de un sueno: una unica ocurrencia en Jueces 7:15 que se distingue de todos los demas sentidos. Cuando Gedeon escucha a un soldado madianita relatar un sueno y ''su interpretacion'' (שִׁבְרוֹ), la palabra probablemente deriva de una raiz homonima distinta, emparentada con el acadio shabaru (''interpretar, adivinar'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138226, 'spa', 'Brechas o grietas estructurales que requieren reparacion', 'Brechas o grietas estructurales que requieren reparacion: una unica ocurrencia en plural en Salmo 60:4, donde el salmista suplica ''sana sus grietas (שְׁבָרֶיהָ)'', hablando de la tierra fracturada como por un terremoto tras la derrota militar. La forma plural y el ruego de ''sanar'' (רָפָא) situan este sentido en la interseccion entre lo fisico y lo metaforico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138230, 'spa', 'Olas rompientes o embates del mar', 'Olas rompientes o embates del mar: una unica ocurrencia en Job 41:25 dentro del poema del Leviatan, donde los embates de la gran criatura marina causan שְׁבָרִים, ''estruendos'' o ''rompientes.'' Esto extiende el campo semantico del sustantivo al ambito maritimo, preservando la imagen central de quiebre violento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138231, 'spa', 'Grano, cereal comercial', 'Grano o cereal visto principalmente como mercancía de intercambio, algo que se compra y vende en tiempos de necesidad. El uso concentrado en Génesis 42-44 (Gn 42:1-2, 19, 26; 43:2; 44:2; 47:14) enmarca esta palabra dentro de la narrativa de la hambruna de José, donde adquirir שֶׁבֶר se convierte en el motor de la trama. Amós 8:5 extiende la dimensión comercial, describiendo mercaderes corruptos que defraudan con balanzas falsas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138240, 'spa', 'Hifil causativo', 'Hifil causativo: hacer cesar, poner fin a — el sentido más frecuente con 33 ocurrencias, donde Dios o un agente humano termina activamente una actividad, condición o institución. Dios hará «cesar» el regocijo de Israel (Os 2:11), pondrá «fin» a la guerra en la tierra (Lv 26:6), y Faraón acusa a Moisés de hacer que el pueblo «cese» de sus labores (Éx 5:5). El árabe abṭala/awqafa confirma el matiz causativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138241, 'spa', 'Qal intransitivo', 'Qal intransitivo: descansar, guardar el sábado — 11 ocurrencias donde la cesación del trabajo es deliberada, mandada y a menudo sagrada. Dios descansó el séptimo día (Gn 2:2-3), el pueblo reposó el séptimo día (Éx 16:30), e incluso la tierra debe «guardar sábado» (Lv 25:2). El árabe istarāḥa pasa del vocabulario de cesación al de reposo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138243, 'spa', 'Qal intransitivo', 'Qal intransitivo: cesar, llegar a su fin — 14 ocurrencias que describen una cesación natural o circunstancial sin un agente explícito que la cause. La siembra y la siega «no cesarán» (Gn 8:22), el maná «cesó» al día siguiente (Jos 5:12), y la obra de Nehemías en el muro no «cesó» (Neh 6:3). El árabe inqaṭaʿa captura el carácter intransitivo de esta detención espontánea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138245, 'spa', 'Nifal pasivo/medio', 'Nifal pasivo/medio: ser llevado a su fin, ser hecho cesar — 4 ocurrencias donde el sujeto experimenta la cesación de forma pasiva. La fortaleza «cesará» de Efraín (Is 17:3), los lugares altos «serán desolados» y cesados (Ez 6:6), y la pompa «será llevada a su fin» (Ez 30:18). El español cesará en voz pasiva confirma el cambio de voz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138246, 'spa', 'Hifil causativo con énfasis en la eliminación o abolición de objetos específicos', 'Hifil causativo con énfasis en la eliminación o abolición de objetos específicos — 5 ocurrencias donde «hacer cesar» implica quitar o eliminar físicamente altares, ídolos, levadura o personal. Josías «abolió» a los sacerdotes idólatras (2 R 23:5), «quitó» los caballos dedicados al sol (2 R 23:11), e Israel debía «eliminar» la levadura de sus casas antes de la Pascua (Éx 12:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138252, 'spa', 'Hifil causativo con el sentido de acallar, silenciar o sofocar — 2 ocurrencias d', 'Hifil causativo con el sentido de acallar, silenciar o sofocar — 2 ocurrencias donde el énfasis recae específicamente en silenciar la oposición o perturbación. En Sal 8:2 Dios ordena alabanza de los niños «para acallar» al enemigo y al vengador, y en Pr 18:18 echar suertes «silencia» las contiendas entre los poderosos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138288, 'spa', 'Cesación/reposo', 'Los tres casos muestran un rango semántico desde reposo forzado por lesión (Éxodo 21:19) hasta cesación honorable de contienda (Proverbios 20:3) hasta posible inactividad (Isaías 30:7, aunque el texto es disputado). El español usa ''reposo'' y ''cesar'', mientras las traducciones varían sobre si el núcleo es descanso, sentarse o cesación. El pasaje de Éxodo muestra más claramente la dimensión económica: tiempo de trabajo perdido que requiere restitución.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138289, 'spa', 'Asiento o morada', 'Designa un asiento, morada o lugar. En 1 Reyes 10:19 «el lugar del asiento» (מְקוֹם הַשֶּׁבֶת) describe la construcción del trono de Salomón. Amós 6:3 condena a quienes establecen «un asiento de violencia» (שֶׁבֶת חָמָס). Números 21:15 usa «hacia la morada de Ar» (לְשֶׁבֶת עָר) para indicar la ubicación del asentamiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138290, 'spa', 'Sábado semanal', 'El día sábado semanal, el séptimo día apartado para el reposo y la adoración, con 68 ocurrencias que constituyen el grupo más numeroso. Es el sábado del Decálogo (Éx 20:8-10), del relato del maná (Éx 16:25-29) y de los llamamientos proféticos a honrar el día (Is 58:13). Español sábado, francés sabbat y alemán Sabbat conservan el préstamo hebreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138292, 'spa', 'Mis sábados (pactuales)', 'Los sábados de Dios como posesión pactual —15 ocurrencias donde el posesivo «mis sábados» (שַׁבְּתוֹתַי) marca la institución como señal entre Dios e Israel. Se concentra en Éxodo 31:13, Levítico 19:3, 19:30, 26:2 y los oráculos de profanación sabática de Ezequiel (Ez 20:12-24; 22:8; 23:38). El posesivo transforma el sábado de regulación temporal en marcador relacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138294, 'spa', 'Reposo sabático solemne', 'Sábado en estado constructo que denota un reposo solemne o intensificado —10 ocurrencias de שַׁבַּת שַׁבָּתוֹן («sábado de completo reposo») y formas constructas similares. Esta duplicación distintiva aparece para el Día de la Expiación (Lv 16:31), el mandamiento sabático semanal (Éx 31:15; 35:2), el año sabático (Lv 25:4) y la primera formulación del reposo en Éx 16:23.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138296, 'spa', 'Sábados colectivos', 'Sábados en plural como institución colectiva —8 ocurrencias que aluden a la observancia sabática regular como categoría junto a novilunios y festividades (1 Cr 23:31; 2 Cr 2:4; 8:13; 31:3; Neh 10:33). Las listas litúrgicas sitúan los sábados junto a los holocaustos y los días festivos, tratando la palabra como un plural institucional más que como días individuales contados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138298, 'spa', 'Sábados posesivos', 'Sábados posesivos de la tierra, la ciudad o el pueblo —10 ocurrencias donde los sábados «pertenecen a» una entidad distinta de Dios. Levítico 26:34-35 constituye el centro teológico: la tierra exiliada «disfrutará de sus sábados» que Israel no guardó, una llamativa personificación donde el suelo mismo reposa. 2 Crónicas 36:21 interpreta el exilio a través de esta lente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138320, 'spa', 'Reposo solemne', 'Un reposo solemne y completo ordenado por Dios para ocasiones sagradas — el sábado semanal (Éx 16:23; 31:15; 35:2), el Día de la Expiación (Lv 16:31; 23:32), los días de fiesta (Lv 23:24, 39) y el año sabático de descanso para la tierra (Lv 25:4-5). Conlleva un matiz de plenitud sagrada que el simple ''descanso'' no capta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138324, 'spa', 'Nombre levítico', 'Los tres casos están en Esdras-Nehemías, identificando a un levita llamado Sabetai involucrado en liderazgo religioso postexílico. El español ''Sabetai'' y transliteraciones varían ligeramente entre versiones. El pasaje de Esdras 10:15 lo muestra entre quienes se oponen al enfoque de la asamblea hacia matrimonios mixtos, mientras Nehemías 8:7 y 11:16 lo representan en roles de enseñanza y supervisión. La recurrencia sugiere una figura influyente en la restauración de la comunidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138326, 'spa', 'Aumentar/multiplicar', 'Los tres usos se dividen entre advertencia contra aumentar pérdida real (Esdras 4:22) y deseos de fórmula de bendición por paz multiplicada (Daniel 4:1, 6:25). El español ''multiplicar'' y términos relacionados aparecen en traducciones. El pasaje de Esdras lo usa negativamente en pregunta retórica sobre por qué el daño debería crecer, mientras los textos de Daniel lo emplean en la fórmula de saludo arameo estándar ''Que tu paz se multiplique''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138328, 'spa', 'Nifal', 'Nifal: ser exaltado. Nifal pasivo-estativo de exaltación aplicado casi exclusivamente a Dios o su nombre. El estribillo de Isaías ''solo Jehová será exaltado'' (2:11, 17) y el himno ''solo su nombre es exaltado'' (Sal 148:13) muestran el término reservado para la majestad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138329, 'spa', 'Nifal', 'Nifal: ser alto, elevado, inaccesible. Nifal que denota altura física, a menudo imponente — muros a punto de quebrarse (Isa 30:13), una ciudad fortificada derribada (Isa 26:5), o un conocimiento demasiado elevado para alcanzar (Sal 139:6). La altura literal y metafórica se difuminan entre sí.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138330, 'spa', 'Qal', 'Qal: ser inaccesiblemente alto. Qal estativo: la conjugación más simple describe algo inherentemente demasiado alto para el acceso humano. Deuteronomio 2:36 reporta que ninguna ciudad fue ''demasiado alta para nosotros'', mientras Job 5:11 eleva al humilde a la prosperidad. Con solo dos apariciones, es la base semántica de la cual elaboran todas las conjugaciones derivadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138331, 'spa', 'Nifal', 'Nifal: estar seguro, a salvo. Sentido especializado del Nifal de seguridad mediante la elevación, atestiguado una vez en Proverbios 18:10: el justo corre al nombre de Jehová ''y es puesto en alto''. La seguridad es el resultado de ser colocado en alto, vinculando el Nifal estativo con la protección causativa del Piel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138332, 'spa', 'Piel', 'Piel: poner en alto, proteger. Piel intensivo-causativo: Dios coloca activamente a alguien en una altura inaccesible como refugio. Central en la teología del Salterio sobre el amparo divino (Sal 20:1; 91:14; 107:41), donde la altura equivale a seguridad más que a mera geografía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138340, 'spa', 'Hifil', 'Hifil: exaltar, elevar. Hifil causativo: exaltar o elevar, presente en Job 36:22 donde Dios ''exalta con su poder''. Es la contraparte transitiva activa de la exaltación pasiva del Nifal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138343, 'spa', 'Pual', 'Pual: ser puesto en alto con seguridad. Pual pasivo del Piel: ser colocado con seguridad en lo alto por la acción de otro. Proverbios 29:25 promete que quien confía en Jehová ''será puesto en alto''. El agente de la elevación es Dios mismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138346, 'spa', 'Errar involuntariamente', 'Expresa errar o pecar sin intención. Levítico 5:18 trata de quien «pecó por inadvertencia» (שָׁגָג) sin saberlo. Números 15:28 provee expiación para «la persona que yerra» (הַנֶּפֶשׁ הַשֹּׁגֶגֶת). Job 12:16 declara que con Dios están «el que yerra y el que hace errar» (שֹׁגֵג וּמַשְׁגֶּה), tanto el engañado como el engañador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138347, 'spa', 'Error, inadvertencia, pecado no intencional', 'Error, inadvertencia, pecado no intencional. Pecado o falta cometida por ignorancia, descuido o inadvertencia y no por desafío deliberado. Es el término técnico en la ley sacerdotal para la transgresión involuntaria, que activa remedios sacrificiales específicos (Lev 4:2; 5:15; Núm 15:25-29). También rige la provisión de ciudades de refugio para el homicidio accidental (Núm 35:11; Jos 20:3, 9). Eclesiastés lo toma prestado para advertir contra los votos descuidados (Ecl 5:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138357, 'spa', 'Extraviarse, vagar, desviarse', 'Extraviarse, vagar, desviarse. Desviarse del camino correcto, ya sea literal o en sentido moral/espiritual. Salmo 119:21 y 119:118 hablan de quienes se desvían de los mandamientos de Dios, y Proverbios 5:23 advierte que el necio morirá por falta de disciplina, extraviándose en su gran insensatez. Proverbios 20:1 dice que el vino es escarnecedor — quien se deja extraviar por él no es sabio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138358, 'spa', 'Errar, cometer un error', 'Errar, cometer un error. Cometer una falta inadvertida o pecado por ignorancia o negligencia. Levítico 4:13 y Números 15:22 usan el verbo para la congregación que peca sin intención, y Job 6:24 y 19:4 presentan a Job concediendo hipotéticamente que puede haber errado. 1 Samuel 26:21 registra a Saúl admitiendo ''he errado''. La distinción con el sentido 1 radica en la falta de intención deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138360, 'spa', 'Embriagarse, extasiarse', 'Embriagarse, extasiarse. Embriagarse o extasiarse — un placentero perderse en el amor o el vino. Proverbios 5:19 exhorta al esposo a estar continuamente extasiado con el amor de su esposa, mientras que el versículo 20 pregunta por qué habría de extasiarse con una extraña. La idea raíz de extraviarse se transforma en absorción extática; el vagar no es fracaso moral sino abandono gozoso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138363, 'spa', 'Hacer errar, extraviar (Hifil)', 'Hacer errar, extraviar (Hifil). Hifil causativo: hacer que alguien se desvíe o extraviar. Deuteronomio 27:18 pronuncia una maldición sobre quien extravía al ciego, y Proverbios 28:10 advierte que quien hace errar al recto caerá en su propia fosa. Job 12:16 atribuye autoridad soberana a Dios: tanto el engañado como el engañador le pertenecen. Salmo 119:10 es la súplica del salmista de no ser dejado errar de los mandamientos divinos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138373, 'spa', 'Nombre propio', 'Nombre propio de dos individuos: (1) Segub, hijo menor de Hiel de Bet-el, quien murió al reconstruir su padre las puertas de Jericó (1 Reyes 16:34), cumpliendo la maldición de Josué (Josué 6:26). La variación Ketiv/Qeré (שְׂגִיב/שְׂגוּב) refleja incertidumbre escribal. (2) Segub hijo de Hezrón por la hija de Maquir, en la genealogía de Judá (1 Crónicas 2:21-22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138374, 'spa', 'Observar atentamente', 'Las tres apariciones muestran diferentes sujetos contemplando: Dios mirando hacia abajo (Salmo 33:14), un amado asomándose (Cantares 2:9), y observadores mirando fijamente al derrotado (Isaías 14:16). El español usa ''observar'' y ''mirar'', mientras el francés emplea ''regarder''. Cada contexto involucra mirar intencional y enfocado en lugar de vista accidental. El pasaje de Isaías lo combina con ''contemplar'', mostrando observación intensa del juicio caído sobre el tirano babilónico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138376, 'spa', 'Sumamente, grandemente (intensificador adverbial)', 'Sumamente, grandemente (intensificador adverbial). Modifica el grado de un verbo o adjetivo en lugar de describir un sustantivo, expresando intensidad superlativa. El rey estaba sumamente furioso (Dan 2:12), Belsasar grandemente turbado (Dan 5:9), Darío sumamente complacido (Dan 6:23), los acusadores completamente destruidos (Dan 6:24) y Daniel profundamente perturbado en su espíritu (Dan 7:28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138377, 'spa', 'Abundante, mucho, muchos (cantidad)', 'Abundante, mucho, muchos (cantidad). Adjetivo cuantitativo que expresa gran número o cantidad. El gran árbol daba fruto abundante suficiente para todos (Dan 4:12, 21), la bestia devoraba mucha carne (Dan 7:5), el rey dio a Daniel muchos regalos (Dan 2:48) y el templo de Jerusalén fue edificado ''hace muchos años'' (Esd 5:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138378, 'spa', 'Grande (en tamaño, importancia o magnitud)', 'Grande (en tamaño, importancia o magnitud). Adjetivo cualitativo que indica grandeza en tamaño, estatura, importancia o magnificencia. La estatua de Nabucodonosor era grande en esplendor y terrible en apariencia (Dan 2:31), y el rey prometió ''gran'' honra y recompensas a quien pudiera interpretar la escritura (Dan 2:6), distinguiéndose de la mera cantidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138382, 'spa', 'Violación sexual', 'Expresa violación o agresión sexual. Deuteronomio 28:30 maldice a los transgresores del pacto: «otro hombre la violará» (יִשְׁגָּלֶנָּה, Ketiv; Qeré יִשְׁכָּבֶנָּה). Isaías 13:16 y Zacarías 14:2 profetizan que invasores violarán a las mujeres (תִּשָּׁגַלְנָה, Ketiv). Jeremías 3:2 acusa a Israel: «¿dónde no fuiste violada?» (שֻׁגַּלְתְּ, Ketiv).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138384, 'spa', 'Consortes del rey', 'Los tres usos están en Daniel 5, describiendo a las mujeres reales convocadas al festín profano de Belsasar. El español ''esposas'' y traducciones similares aparecen, aunque el término denota específicamente consortes en lugar de la reina madre (quien llega por separado en 5:10). La repetición en los versículos 2, 3 y 23 enfatiza el sacrilegio deliberado y escalado de profanar los vasos del templo en una fiesta que involucra al harén real, multiplicando la ofensa contra los objetos santos de Yahvé.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138385, 'spa', 'Estar loco, enloquecer', 'Ser llevado a la locura o comportarse como demente, abarcando la insania genuina como maldicion divina (Dt 28:34), la locura fingida como estrategia de supervivencia (1 S 21:14-16, David ante Aquis) y la caracterizacion despectiva del extasis profetico (Os 9:7; 2 R 9:11). El Hitpael añade el matiz de hacerse deliberadamente el loco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138390, 'spa', 'Locura o frenesí', 'Las tres apariciones abarcan maldición del pacto (Deuteronomio 28:28), estilo de conducir metafórico (2 Reyes 9:20), y guerra escatológica (Zacarías 12:4). El español ''locura'' y el francés ''folie'' aparecen consistentemente. El pasaje de Deuteronomio la enumera entre juicios devastadores, mientras Zacarías la aplica a caballos de guerra, creando pánico. El texto de 2 Reyes la usa hiperbólicamente para el característico manejo furioso de Jehú, sugiriendo velocidad temeraria y agresividad descontrolada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138391, 'spa', 'Cría del ganado', 'La cría o prole de animales domésticos, señal de bendición o maldición divina. En Éx 13:12 designa la primera cría consagrada al SEÑOR. Deuteronomio la empareja con las crías del rebaño en bendiciones del pacto (7:13; 28:4) y maldiciones (28:18, 51), donde la pérdida de שֶׁגֶר señala juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138392, 'spa', 'Pecho (parte del cuerpo)', 'Pecho (parte del cuerpo). El pecho femenino, usado en contextos literales, figurados y alegóricos. El Cantar de los Cantares emplea la forma dual para la belleza íntima (Cant 4:5; 7:4; 8:10); Oseas 9:14 invoca pechos secos como maldición; Ezequiel 23:3, 21 usa la imagen en alegoría nacional. Salmo 22:9 y Job 3:12 hacen referencia a la lactancia en la más temprana infancia. Lamentaciones 4:3 lo extiende a la lactancia animal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138408, 'spa', 'Pecho materno', 'Los tres usos incluyen lactancia literal (Job 24:9) y metáforas extendidas de succionar de pechos reales (Isaías 60:16) o del pecho consolador de Jerusalén (66:11). El español ''pecho'' y términos relacionados aparecen. El doble uso de Isaías desarrolla la metáfora de la lactancia: primero describiendo la riqueza gentil fluyendo a Israel como mamar de reyes, luego representando a Jerusalén restaurada como madre cuyos hijos maman consolación y satisfacción de su pecho abundante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138410, 'spa', 'El sentido predominante de destrucción y devastación como estado o resultado — c', 'El sentido predominante de destrucción y devastación como estado o resultado — ciudades arrasadas, pueblos arruinados, tierras desoladas. El juego de palabras de Isaías 13:6 ''keshod mishaddai'' vincula la devastación con el juicio divino. Abarca la mayoría de los usos proféticos y poéticos (Job 5:21-22, Isa 16:4, 22:4, 51:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138414, 'spa', 'El sentido activo de violencia, robo y despojo — que enfatiza la perpetración má', 'El sentido activo de violencia, robo y despojo — que enfatiza la perpetración más que las consecuencias. Emparejado con hamas en Ezequiel 45:9 y Amós 3:10, acusa a los poderosos de oprimir a los vulnerables. El Salmo 12:5 lo fundamenta en la respuesta de Dios: Él se levanta por causa del despojo de los pobres.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138423, 'spa', 'Una lectura verbal singular del ketiv en Proverbios 11', 'Una lectura verbal singular del ketiv en Proverbios 11:3, donde el texto consonántico preserva una forma finita Qal que significa ''él destruye,'' distinta de los usos nominales en otros pasajes. La tradición qeré probablemente la normaliza, pero el ketiv atestigua un uso verbal vivo de la raíz en la literatura sapiencial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138424, 'spa', 'Rastrillar el suelo', 'Las tres apariciones involucran rastrillado como preparación agrícola: retóricamente en Isaías 28:24 (en paralelo con arar), figuradamente en Oseas 10:11 (Jacob rastrillará), e imposiblemente en Job 39:10 (¿puedes hacer que el buey salvaje rastrille?). El español usa ''rastrillar'' o ''arar'', mientras las traducciones varían en el implemento agrícola específico. El pasaje de Isaías distingue el rastrillado del arado, mostrando la secuencia normal de preparación del suelo antes de sembrar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138425, 'spa', 'Participio activo Qal usado como sustantivo agentivo — «destructor, saqueador» —', 'Participio activo Qal usado como sustantivo agentivo — «destructor, saqueador» — en 15 ocurrencias. Esta forma nombra al invasor u opresor como personaje del drama profético: el «destructor» del que Isaías 16:4 promete refugio a Moab, los destructores emparejados de Isaías 21:2. El francés pillards y el alemán Plünderer captan la índole merodeadora de esta figura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138426, 'spa', 'Pual pasivo (20 ocurrencias)', 'Pual pasivo (20 ocurrencias): estado resultante de haber sido devastado o asolado, aplicado a ciudades, tierras y pueblos que ya han sufrido destrucción. El oráculo de Isaías contra Moab abre con dos ciudades «asoladas en una noche» (Is 15:1), y Tiro escucha el clamor «eres destruida» desde las naves que regresan (Is 23:1, 14). El español asolada y el alemán verwüstet captan este sentido resultativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138433, 'spa', 'Formas finitas, imperativos e infinitivos Qal activos que expresan la acción ver', 'Formas finitas, imperativos e infinitivos Qal activos que expresan la acción verbal de destruir o despojar (11 ocurrencias). Se trata del evento dinámico en sí, no del agente ni del resultado: los enemigos de Dios «que me despojan» (Sal 17:9), la traición de los infieles «los destruirá» (Pr 11:3), y el imperativo «¡saquead!» lanzado contra Cedar (Jer 49:28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138434, 'spa', 'Formas intensivas Piel (3 ocurrencias) que expresan destrucción o arruinamiento ', 'Formas intensivas Piel (3 ocurrencias) que expresan destrucción o arruinamiento deliberado e intensificado. Proverbios 19:26 describe a un hijo que «arruina» a su padre y expulsa a su madre, donde el Piel intensifica la violencia más allá del mero saqueo. Oseas 10:2 anuncia que Dios «destruirá» los altares de Israel. El cambio del español destruir a arruinar marca la intensificación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138438, 'spa', 'Participios pasivos Qal, imperfectos pasivos y formas Nifal (7 ocurrencias) que ', 'Participios pasivos Qal, imperfectos pasivos y formas Nifal (7 ocurrencias) que expresan el proceso o estado de ser destruido, distinto del resultativo Pual. Jueces 5:27 emplea el participio pasivo Qal para Sísara: «donde se hundió, allí cayó, destruido.» El salmista se dirige a Babilonia como «la devastada» en Salmo 137:8. Isaías 33:1 juega con lo activo y lo pasivo simultáneamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138453, 'spa', 'Un único infinitivo absoluto Qal en Miqueas 2', 'Un único infinitivo absoluto Qal en Miqueas 2:4 que funciona como intensificador adverbial del verbo finito: «somos del todo despojados.» El español del todo capta el doblamiento enfático (שָׁדוֹד נֻשַּׁדֻּנוּ), recurso clásico de intensificación hebrea donde el infinitivo absoluto amplifica la finalidad de la ruina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138463, 'spa', 'Campo (terreno abierto, tierra cultivada)', 'Campo (terreno abierto, tierra cultivada). Terreno abierto o campiña, empleado en poesía como variante arcaica de שָׂדֶה. Abarca tierra cultivada que produce alimento (Dt 32:13; Os 10:4; Lm 4:9), el hábitat silvestre de las bestias (בְּהֵמוֹת שָׂדַי, Sal 8:8; Jl 2:22; חַיְתוֹ שָׂדַי, Is 56:9; Sal 104:11) y terreno amplio en paralelismo con mar y mundo (Sal 96:12, cf. 98:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138468, 'spa', 'Campo cultivado', 'Campo cultivado, parcela agrícola en propiedad (316 veces): el sentido abrumadoramente dominante. Comprende campos que se aran, siembran, cosechan, compran, venden y heredan. Incluye formas constructas (שְׂדֵה-מוֹאָב, «el territorio de Moab», Rut 1:1) y todas las flexiones con preposiciones y sufijos. Génesis 23:17 registra la compra del campo de Macpela; Levítico 25:3 legisla el reposo sabático de la tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138486, 'spa', 'Campo abierto, llanura', 'Campo abierto o llanura con nombre propio (3 veces), usado geográficamente para designar una extensión amplia e inculta, no una parcela agrícola delimitada. Los Salmos 78:12 y 78:43 mencionan «el campo de Zoán» —la región en torno a la ciudad egipcia— y Oseas 12:12 alude a la huida de Jacob al «campo de Aram». Aquí שָׂדֶה funciona casi como elemento toponímico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138488, 'spa', 'Terreno silvestre', 'Terreno silvestre o no cultivado (2 veces), ambas en 2 Reyes 4:39, donde alguien sale al «campo» (הַשָּׂדֶה) a recoger calabazas silvestres y encuentra una «vid silvestre» (גֶּפֶן שָׂדֶה). La doble aparición en un solo versículo subraya que no se trata de tierra de labranza sino de suelo agreste donde crecen plantas salvajes. Este sentido tiende un puente entre el campo cultivado y la campiña abierta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138522, 'spa', 'Nombre o epíteto divino tradicionalmente traducido como «el Todopoderoso», usado', 'Nombre o epíteto divino tradicionalmente traducido como «el Todopoderoso», usado en dos ámbitos principales: la alianza patriarcal, donde Dios se revela como El Shaddai (Gn 17:1; 35:11; Éx 6:3), y los diálogos poéticos de Job, donde Shaddai es la designación divina predominante (Job 5:17; 8:3; 11:7; 31:2). También aparece en los oráculos de Balaam (Nm 24:4, 16) y en textos proféticos de juicio (Is 13:6; Jl 1:15). La Septuaginta lo traduce como pantokrátor y la Vulgata como omnipotens.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138530, 'spa', 'Nombre propio masculino', 'Nombre propio masculino que significa ''שַׁדַּי es llama'' o ''el Todopoderoso es luz'', portado por el padre de Elisur, lider de la tribu de Ruben. Todas las apariciones corresponden a material sacerdotal en Numeros: el censo (1:5), la disposicion del campamento (2:10), las ofrendas de dedicacion del tabernaculo (7:30, 35) y el orden de marcha (10:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138531, 'spa', 'Valle de Sidim', 'Las tres apariciones están en Génesis 14, identificando el valle como sitio de batalla de los cinco reyes contra cuatro. El texto lo equipara explícitamente con el Mar Salado (14:3), sugiriendo que lectores posteriores sabían que este valle había sido transformado. El español ''Sidim'' y otras versiones transliteran el nombre. La mención en el versículo 10 de los pozos de asfalto del valle proporciona detalles geográficos sobre la topografía anterior al Mar Muerto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138533, 'spa', 'Campo cultivado', 'Campo cultivado o tierra agrícola en terrazas, siempre en plural en el hebreo bíblico. Se emplea para tierras de labranza literales (Deut 32:32; 2 Re 23:4) y poéticamente para terrenos productivos cuya devastación señala juicio divino (Isa 16:8; Hab 3:17). Jeremías 31:40 designa un lugar específico cerca de Jerusalén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138538, 'spa', 'Grano quemado', 'Los tres usos modifican ''espigas de grano'' en el segundo sueño del Faraón (Génesis 41:6, 23, 27), paralelo al sueño de las vacas flacas. El español ''quemadas'' y términos compuestos en alemán capturan la quemadura por el viento del este. La repetición refleja la doble narración del sueño y la interpretación de José, enfatizando la imagen vívida del grano arruinado por el viento. El ''viento del este'' (קָדִים) aparece consistentemente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138540, 'spa', 'Plaga agricola', 'Tizon o anublo: enfermedad fungica que abrasa y ennegrece el grano antes de la cosecha, siempre emparejada con יֵרָקוֹן (moho). Funciona como instrumento de maldicion pactual (Dt 28:22) y senal de disciplina agricola divina (Am 4:9; Hag 2:17). Salomon la enumera entre las calamidades que demandan oracion nacional (1 R 8:37; 2 Cr 6:28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138542, 'spa', 'Filas o hileras', 'Designa filas o hileras en contextos militares y posiblemente arquitectónicos. En 2 Reyes 11:8, 15 (= 2 Crónicas 23:14), se ordena a los guardias mantenerse en las filas (בַּשְּׂדֵרוֹת), y quien quebrante la formación debe morir. En 1 Reyes 6:9, la frase גֵּבִים וּשְׂדֵרֹת בָּאֲרָזִים describe parte del techo del templo, probablemente tablones o vigas de cedro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138544, 'spa', 'Sadrac (nombre propio babilónico)', 'Sadrac (nombre propio babilónico). El nombre propio Sadrac (שַׁדְרַךְ), nombre babilónico dado al exiliado judío Hananías. Las 14 ocurrencias se encuentran dentro de Daniel 2-3, concentradas en la narrativa del horno de fuego (Dan 3:12-30). Las transliteraciones entre lenguas --inglés ''Shadrach,'' español ''Sadrac,'' francés ''Schadrac,'' alemán ''Schadrach''-- muestran mínima variación, reflejando el préstamo directo de la forma aramea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138545, 'spa', 'Un animal individual del rebano, referido genericamente a una oveja o cabra como', 'Un animal individual del rebano, referido genericamente a una oveja o cabra como unidad de ganado menor, sin enfasis en la edad ni en proposito sacrificial. Las leyes de propiedad en Exodo (22:1, 4, 9) enumeran שֶׂה junto a שׁוֹר (buey) y חֲמוֹר (asno) como ganado estandar. Genesis 30:32 lo usa en el contexto del acuerdo de Laban sobre el rebano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138546, 'spa', 'Un animal joven del rebano, un cordero o cabrito, destacado por contextos sacrif', 'Un animal joven del rebano, un cordero o cabrito, destacado por contextos sacrificiales, pascuales o figurados. El שֶׂה pascual de Exodo 12:3-5 debe ser un macho de un ano; Isaias 53:7 compara al Siervo con un שֶׂה llevado al matadero. Genesis 22:7-8, donde Isaac pregunta ''¿donde esta el cordero?'', gira sobre este sentido preciso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138565, 'spa', 'Ónice (piedra preciosa)', 'Piedra preciosa tradicionalmente identificada como ónice, usada en el efod y pectoral del sumo sacerdote (Éx 25:7; 28:9, 20; 35:9, 27), entre las riquezas del Edén (Gn 2:12), en las provisiones de David para el templo (1 Cr 29:2) y como medida del valor incomparable de la sabiduría (Job 28:16). Su identificación exacta sigue siendo debatida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138572, 'spa', 'Ornamentos lunares', 'Las tres apariciones describen medias lunas en camellos madianitas (Jueces 8:21, 26) y entre ornamentos femeninos (Isaías 3:18). El español ''lunetas'' y términos similares capturan la forma lunar. Los pasajes de Jueces las muestran como artículos prestigiosos usados por reyes enemigos y sus camellos, saqueados por Gedeón. Isaías las lista entre bienes de lujo destinados a ser removidos en el juicio, sugiriendo su valor como símbolos de estatus y riqueza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138575, 'spa', 'Ruina, devastación', 'Devastación, ruina o desolación — destrucción catastrófica vista como estado o evento. Se usa del juicio divino sobre los malvados (Sal 35:8; 63:10), de la ruina repentina (Pr 3:25; Is 10:3), del derrocamiento de Babilonia (Is 47:11) y de los yermos donde Job vaga (Job 30:3, 14). Sofonías 1:15 empareja שׁוֹאָה con מְשׁוֹאָה al describir el Día del SEÑOR.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138576, 'spa', 'Tempestad, tormenta', 'Una tormenta o tempestad violenta — la palabra desplegada en símiles explícitos para evocar la fuerza repentina y abrumadora de la calamidad. Proverbios 1:27 advierte que el espanto vendrá ''como tempestad'' (כְּשׁוֹאָה, en paralelo con סוּפָה ''torbellino''), y Ezequiel 38:9 describe la invasión de Gog ascendiendo ''como tempestad'' (כַּשֹּׁאָה, en paralelo con עָנָן ''nube'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138585, 'spa', 'Vacuidad, vanidad, inutilidad — el sentido más amplio y frecuente con 29 ocurren', 'Vacuidad, vanidad, inutilidad — el sentido más amplio y frecuente con 29 ocurrencias. Abarca la cualidad abstracta de carecer de sustancia real o valor duradero. Los meses de Job son «meses de vacuidad» (Job 7:3); el salmista rechaza los «ídolos de שָׁוְא» (Sal 31:6); Oseas declara que Galaad «se ha vuelto nada» (Os 12:12). El alemán Nichtigkeit y el francés vanité captan este vacío metafísico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138586, 'spa', 'En vano, sin propósito — el uso adverbial que aparece 17 veces, a menudo con la ', 'En vano, sin propósito — el uso adverbial que aparece 17 veces, a menudo con la preposición lamed. El לַשָּׁוְא del Tercer Mandamiento (Éx 20:7; Dt 5:11) es el caso paradigmático: tomar el nombre de Dios «sin propósito alguno». El Salmo 127:2 declara «vano es (שָׁוְא) para vosotros madrugar». El español en vano y el francés en vain seleccionan vocabulario de fracaso de propósito.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138592, 'spa', 'Falsedad, engaño, mentira — 6 ocurrencias donde predomina la dimensión moral del', 'Falsedad, engaño, mentira — 6 ocurrencias donde predomina la dimensión moral del engaño deliberado. La variante del Noveno Mandamiento usa שָׁוְא para «falso testimonio» (Dt 5:20, en contraste con שֶׁקֶר en Éx 20:16), y el Salmo 144:8 describe «una diestra de falsedad». El español falsedad y el francés faux seleccionan vocabulario específico de engaño.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138607, 'spa', 'Destrucción o fuerza devastadora — una única ocurrencia en Isaías 30', 'Destrucción o fuerza devastadora — una única ocurrencia en Isaías 30:28 donde el aliento de Dios es como un torrente desbordante que llega «hasta el cuello» para zarandear a las naciones con «el cedazo de שָׁוְא». El español destrucción y el inglés destruction se apartan de las traducciones habituales de vanidad, sugiriendo que este contexto activa un raro sentido de aniquilación destructiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138609, 'spa', 'Una ocurrencia limítrofe en Jonás 2', 'Una ocurrencia limítrofe en Jonás 2:8, donde los que se aferran a «ídolos de שָׁוְא» (הַבְלֵי־שָׁוְא) abandonan su lealtad al pacto. El español falsedad y el francés vanité se dividen entre los sentidos de vacuidad y falsedad. Este versículo combina el motivo de la idolatría como vacuidad (cf. Sal 31:6) con el tema de la traición al pacto, situándose en la intersección de los sentidos 1 y 3.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138613, 'spa', 'volver, regresar (Qal)', 'El sentido Qal fundamental: retorno físico o espacial a un lugar, persona o condición previa. Con 874 apariciones es el significado por defecto en todos los contextos narrativos. Las glosas multilingües rinden consistentemente movimiento direccional — español volvió, francés retourna, alemán kehrte zurück. Pasajes clave como Gn 8:9 (la paloma regresando al arca) y Gn 22:19 (Abraham volviendo del Moriá) lo ilustran.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138642, 'spa', 'hacer volver, restaurar (Hifil)', 'El causativo Hifil: hacer que alguien o algo regrese, restaurar a un estado anterior. Abarca contextos militares (hacer volver cautivos), legales (devolver prendas empeñadas, Dt 24:13) y promesas proféticas de restauración nacional (Gn 48:21, ''Dios os hará volver''). El francés ramènerai y el español haré volver captan la fuerza causativa que lo distingue del retorno simple.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138647, 'spa', '¡volved!, llamada al arrepentimiento', 'Usos imperativos y exhortatorios que llaman al arrepentimiento — ''¡volved!'' — concentrados en apelaciones proféticas. Ez 14:6, 18:30 y 33:11 presentan llamados urgentes a volverse de los ídolos. Pr 1:23 personifica a la Sabiduría haciendo el mismo ruego. El español volveos preserva la urgencia reflexiva. Estas apariciones funcionan como puente exhortatorio entre el retorno espacial y la conversión teológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138709, 'spa', 'responder, replicar (Hifil)', 'Un uso idiomático del Hifil que significa ''devolver una palabra'', es decir, responder o replicar. La construcción toma típicamente דָּבָר (palabra) como objeto. Rt 1:21 y Est 4:13 muestran claramente este patrón. El español responderé capta el desplazamiento semántico del movimiento al habla, mientras otras lenguas retienen a menudo la metáfora literal de ''devolver''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138745, 'spa', 'rechazar, retribuir (Hifil)', 'El Hifil empleado para rechazo hostil o retribución: repeler enemigos, apartar la ira o devolver el mal. Dt 32:41 (''haré volver la venganza'') y 2 S 22:25 muestran a Dios devolviendo las consecuencias sobre los agentes. El español retribuyó y dales retribución subrayan la lógica recíproca. El cognado sabeo porta igualmente fuerza retributiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138756, 'spa', 'apartarse, apostatar (Qal)', 'Qal con מִן o מֵאַחֲרֵי indicando defección: apartarse de Dios, apostasía. Jos 22:18 advierte a Israel contra apartarse, y 1 S 15:11 registra cómo Saúl se apartó de seguir al Señor. El español se apartó y el alemán wende weg captan la deserción espiritual. Solo 7 apariciones, pero proféticamente significativas como espejo oscuro del arrepentimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138767, 'spa', 'restaurar, renovar (Polel/Piel)', 'El tema intensivo Polel/Piel que expresa restauración profunda o repetida. El Sal 23:3 (''restaura mi alma'') es el caso paradigmático, usando el intensivo para transmitir renovación espiritual profunda. Is 58:12 (''restaurador de sendas'') y Jr 50:19 (''haré volver a Israel a su pasto'') expresan restablecimiento integral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138834, 'spa', 'restitución, lo devuelto', 'Una forma nominal o participial pasiva rara que aparece en Nm 5:8 en el contexto de la ley de restitución — ''lo devuelto'', es decir, el pago de restitución en sí. El español la devuelta y el francés le retourna confirman la lectura sustantival. Esta única aparición cristaliza el rango semántico del verbo en un sustantivo concreto: la cosa que se restituye.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138919, 'spa', 'Apóstata o rebelde', 'Describe a quienes se apartan de Dios. En Jeremías 3:14, 22, Dios llama «Volved, hijos rebeldes» (שׁוּבוּ בָּנִים שׁוֹבָבִים), jugando con la raíz שׁוּב. Isaías 57:17 habla de quien sigue שׁוֹבָב en su propio camino pese al castigo divino. El término subraya la apostasía voluntaria y persistente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138920, 'spa', 'Nombre propio', 'Nombre de dos individuos: (1) Sobab, hijo de David nacido en Jerusalén, mencionado en 2 Samuel 5:14, 1 Crónicas 3:5 y 14:4; (2) Sobab, hijo de Caleb con Azuba, en 1 Crónicas 2:18. El nombre posiblemente deriva de la raíz שׁוּב en el sentido de «apartarse, apostasía» (cf. H7726 שׁוֹבָב), aunque los nombres propios no siempre conservan su carga etimológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138921, 'spa', 'Infiel, apóstata', 'Los tres usos incluyen a Israel caracterizado como infiel (Jeremías 31:22), Amón como apóstata (49:4), y un texto disputado en Miqueas 2:4. El español ''rebelde'' y términos relacionados aparecen, aunque algunas traducciones usan ''apóstata'' o ''infiel''. El doble uso de Jeremías aplica el epíteto tanto a Israel como a sus enemigos, sugiriendo apostasía generalizada. La forma femenina ''hija'' personaliza la acusación como relación rota.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138925, 'spa', 'Sobal (nombre propio)', 'El nombre personal y de clan שׁוֹבָל, que designa al menos dos o tres individuos: un jefe horita/edomita descendiente de Seir (Gn 36:20, 23, 29; 1 Cr 1:38, 40), un hijo de Hur y nieto de Caleb asociado con Quiriat-jearim (1 Cr 2:50, 52), y una figura en la línea de Judá (1 Cr 4:1-2). La superposición entre genealogías edomitas y judaítas puede reflejar migraciones históricas o integraciones territoriales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138932, 'spa', 'Ser igual, valer', 'Ser igual, valer. Qal y Nithpael: ser igual a, comparable con, o de valor equivalente. Ester emplea este sentido tres veces en cálculos políticos de valor (3:8; 5:13; 7:4), mientras Proverbios 3:15 declara que nada ''iguala'' a la sabiduría. Job 33:27 lo usa para la retribución moral: lo que no fue pagado en su justa medida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138934, 'spa', 'Poner, colocar delante', 'Poner, colocar delante. Uso distintivo del Piel que significa colocar algo deliberadamente en una posición fija. Salmo 119:30 dice ''Tus juicios puse delante de mí'': no comparar ni nivelar, sino posicionar algo como punto de referencia constante. Este sentido surge naturalmente de la idea raíz de disponer de manera uniforme y estable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138935, 'spa', 'Nivelar, alisar, aquietar', 'Nivelar, alisar, aquietar. Piel factitivo: hacer llano, liso o calmo. Isaías 28:25 describe a un agricultor que ha ''nivelado'' la superficie de su campo antes de sembrar, una acción agrícola concreta. Salmo 131:2 lo extiende metafóricamente: ''He aquietado y acallado mi alma,'' preservando tanto la dimensión física como la psicológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138939, 'spa', 'Hacer igual, asemejar', 'Hacer igual, asemejar. Hifil causativo: hacer algo igual a otro, asemejar o comparar. Este sentido aparece en audaces preguntas retóricas: ''¿A quién me haréis semejante y me igualaréis?'' (Is 46:5) y ''¿A qué te compararé, hija de Jerusalén?'' (Lm 2:13), mostrando la fuerza activa y comparativa del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138944, 'spa', 'Poner, colocar, otorgar', 'Poner, colocar u otorgar algo deliberadamente ante o sobre alguien. El salmista en Sal 16:8 lo usa para describir el acto de poner a YHWH delante de si como ancla permanente, mientras que Sal 89:19 habla de Dios otorgando fuerza a un heroe. Oseas 10:1 extiende el uso al sentido de producir fruto, sugiriendo una colocacion productiva e intencional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138945, 'spa', 'Nivelar, afianzar', 'Nivelar, emparejar o dar pie seguro, usado como participio Piel describiendo el don divino de estabilidad. En los pasajes paralelos de 2 S 22:34 y Sal 18:33, se describe a Dios haciendo los pies del fiel como los de una cierva en terreno elevado, transmitiendo tanto la destreza fisica como la seguridad espiritual que proviene de la gracia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138956, 'spa', 'Hundirse o abatirse', 'El verbo representa un movimiento descendente: hundirse en el polvo (Sal 44:25), descender hacia la muerte (Prov 2:18) o el alma que se abate bajo la aflicción (Lam 3:20). Abarca desde la postración física en adoración hasta el colapso metafórico, mostrando la fuerza gravitatoria hacia la mortalidad y la humillación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138958, 'spa', 'Fosa o trampa', 'Fosa u hoyo en el suelo, usado literalmente para terreno desolado y figuradamente para traicion o peligro moral. Jeremias 2:6 lo empareja con la sequedad evocando desolacion. En Jer 18:20 y 18:22 los enemigos cavan una fosa para el profeta, metaforizando conspiracion letal. Proverbios 22:14 y 23:27 llaman a la boca de la mujer ajena ''fosa profunda'', simbolizando trampa moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138960, 'spa', 'Gentilicio de Bildad', 'Gentilicio que identifica a Bildad como descendiente de שׁוּחַ, hijo de Abraham con Cetura. Las cinco apariciones se vinculan a Bildad en Job (2:11; 8:1; 18:1; 25:1; 42:9). Las traducciones lo vierten uniformemente como demonimo (''el suhita'', ''the Shuhite''), confirmando su funcion de identificador etnico y no de nombre personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138964, 'spa', 'Ir de un lado, vagar (Qal)', 'Qal básico: ir de un lado a otro, vagar o recorrer un área. Describe el movimiento general a través de un espacio: el pueblo dispersándose para recoger el maná (Nm 11:8), los hombres de David recorriendo la tierra (2 S 24:2, 8) y Satanás vagando por la tierra (Job 1:7; 2:2). Capta la cualidad de un desplazamiento pausado y exploratorio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138965, 'spa', 'Recorrer con afán (Piel)', 'Polel/Piel intensivo: recorrer ávidamente de un lado a otro, correr con propósito o desesperación. Los ojos del SEÑOR recorren toda la tierra buscando a los fieles (2 Cr 16:9; Zac 4:10); Amós 8:12 muestra el extremo desesperado: personas corriendo de norte a este buscando la palabra de Dios sin hallarla. Daniel también emplea esta forma para describir una búsqueda intensa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138968, 'spa', 'Vagar inquietamente (Hitpael)', 'Hitpael reflexivo-iterativo: vagar sin rumbo, deambular sin dirección. Solo aparece en Jeremías 49:3, donde se exhorta a las hijas de Rabá a correr frenéticamente entre los cercados. El término sugiere una huida caótica y sin destino, un matiz más oscuro del sentido errante de esta raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138975, 'spa', 'Látigo, azote', 'Látigo o azote usado para infligir castigo, apareciendo tanto en sentido literal como metafórico. Literalmente designa el instrumento de disciplina: Roboam amenaza con azotes más duros que los de Salomón (1 R 12:11, 14). Metafóricamente, Job 5:21 habla del ''azote de la lengua'', mientras Isaías describe a Dios blandiendo un azote contra los opresores (Is 10:26; 28:15, 18). Nahúm 3:2 evoca el chasquido del látigo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138983, 'spa', 'Soco (toponimo en Juda)', 'Toponimo en el territorio de Juda que designa una o dos ciudades. La Soco de la Sefela (Jos 15:35) es donde los filisteos acamparon antes de la batalla de David y Goliat (1 S 17:1), fortificada por Roboam (2 Cr 11:7) y tomada bajo Acaz (2 Cr 28:18). Otra Soco aparece en la zona montañosa cerca de Hebron (Jos 15:48).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138989, 'spa', 'Dobladillo, falda, cola', 'El dobladillo, falda o cola en el borde inferior de una vestidura, empleado en tres registros interconectados: vestimentas sacerdotales donde campanillas y granadas adornan los bordes del manto del efod (Ex 28:33-34; 39:24-26), visión teofánica donde la cola de Dios llena el templo (Is 6:1), y metáfora profética donde las faldas expuestas o ensangrentadas significan vergüenza y culpa (Jer 13:22, 26; Nah 3:5; Lm 1:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138995, 'spa', 'Descalzo o despojado', 'Describe el estado de ir descalzo o despojado de calzado, siempre en contextos de humillación, juicio o actos proféticos simbólicos. Dios conduce descalzos a consejeros y sacerdotes (Job 12:17, 19), despojándolos de dignidad. Miqueas camina descalzo y desnudo como lamento profético (Miq 1:8). El término enfatiza la vulnerabilidad y la vergüenza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (138999, 'spa', 'Convertir en, hacer', 'Este sentido transformativo (91 ocurrencias) muestra el verbo con el significado de «hacer» o «convertir en», como cuando Dios promete hacer la descendencia de Abraham como el polvo de la tierra (Gn 13:16) o como granos de arena incontables (Gn 32:12). Las traducciones al árabe, coreano y suajili suelen desplazarse a verbos de creación o transformación, revelando un grupo semántico distinto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139000, 'spa', 'Poner, colocar', 'El sentido físico nuclear de colocar un objeto en un lugar aparece 444 veces y domina el uso bíblico. Las glosas multilingües (español puso, francés mit, alemán legte) lo rinden de forma coherente sin extensión metafórica. Pasajes clave incluyen Génesis 22:6 (Abraham poniendo la leña sobre Isaac) y Génesis 28:11 (Jacob colocando una piedra como almohada), donde la acción es concreta y espacial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139098, 'spa', 'Dar, otorgar', 'Solo 3 ocurrencias muestran este sentido extendido de dar u otorgar, como en Números 6:26 («el Señor te dé paz») y Josué 7:19 («da gloria al Señor»). El campo semántico se ha desplazado de la colocación espacial a la transferencia de bendición u honor, situando este sentido en la frontera con el dominio económico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139099, 'spa', 'Designar, establecer', 'Con 23 apariciones, este sentido cubre el nombramiento o la instalación de alguien en una posición de autoridad. Éxodo 1:11 describe a capataces puestos sobre Israel, y Éxodo 2:14 recoge la pregunta «¿Quién te ha puesto por príncipe y juez sobre nosotros?». El objeto personal y el contexto de autoridad lo distinguen de la mera colocación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139138, 'spa', 'Poner el corazón', 'La expresión idiomática «poner el corazón» (שִׂים לֵב) abarca 13 usos con el significado de prestar atención, considerar o tomar nota. La frase señala un enfoque cognitivo más que una acción física. Las traducciones al coreano y al japonés emplean verbos mentales («considerar», «tomar a pecho») que desambiguan claramente este sentido del de la colocación concreta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139191, 'spa', 'Establecer (cósmico)', 'Job 38:33 constituye un caso aislado: «¿Puedes establecer las leyes del cielo?». La glosa «establecer» podría alinear este uso con el sentido de designar o colocar, pero la única ocurrencia y el contexto cósmico dejan la acepción ambigua, a medio camino entre los sentidos 1 y 3.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139192, 'spa', 'Poner al frente', 'Génesis 47:6 ordena «ponlos al frente de mi ganado», separado del sentido 3 (designar). Puede tratarse de una sobresegmentación, ya que ambos implican situar personas en posición de autoridad. El español y-ponlos y el alemán dann-setze-sie emplean verbos de colocación simple, lo que sugiere que la noción de autoridad no está fuertemente marcada aquí.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139202, 'spa', 'Poner entre los vivos', 'El Salmo 66:9 describe «al que pone nuestra alma entre los vivos», una única ocurrencia que parece ser una variante poética del sentido 1 (colocación). La forma participial y el contexto existencial podrían justificar la separación, pero la evidencia multilingüe no revela un grupo semántico distinto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139204, 'spa', 'Poner atención', 'Job 4:20 pregunta «¿Hay alguien que lo note?», con un sentido relacionado con el sentido 4 (poner el corazón). La única ocurrencia y el contexto interrogativo lo convierten en candidato a fusión con la acepción de atención cognitiva, pues ambos implican un acto de percepción interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139227, 'spa', 'Poner como vestidura', 'Job 38:9 («cuando puse la nube por vestidura») puede pertenecer al sentido 2 (convertir en) o al sentido 1 (colocar). La única ocurrencia, dentro del discurso creacional de Dios, sugiere un acto transformativo, pero los datos lo han aislado. Las traducciones al árabe y al español emplean verbos de colocación simple.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139237, 'spa', 'Disponer un lugar', '1 Crónicas 17:9 («Dispondré un lugar para mi pueblo») hace eco del sentido de designación (sentido 3) pero ha sido separado. La promesa futura y el objeto locativo («un lugar») mezclan los sentidos 1 y 3. Es un fuerte candidato a consolidación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139241, 'spa', 'Conceder paz', 'El Salmo 147:14 describe «al que pone paz en tus fronteras», otra ocurrencia aislada que se solapa con los sentidos 1 o 5 (otorgar). La forma participial y el contexto de bendición lo alinean con la acepción de dar u otorgar, aunque la preposición espacial («en tus fronteras») conserva un matiz de colocación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139277, 'spa', 'Poner, designar', 'Las tres apariciones incluyen 2 Samuel 13:32 (posiblemente ''determinado'' o un problema textual) e Isaías 10:6 dos veces (designando algo para ser pisoteado). Las traducciones varían ampliamente, algunas viéndolo como formas de ''poner/colocar'' y otras proponiendo enmiendas. Las versiones en español y francés muestran incertidumbre, a veces omitiendo o parafraseando. El contexto de Isaías involucra la designación divina del destino de Asiria como instrumento de juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139278, 'spa', 'El Nifal pasivo', 'El Nifal pasivo: ser colocado, establecido o emitido. Los decretos ''son promulgados,'' los fondos ''son asignados'' y los permisos ''son otorgados.'' Esdras 4:19 informa que ''se emitió un decreto'' para revisar los archivos, y Esdras 6:11 advierte del castigo si el decreto ''es violado.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139279, 'spa', 'El significado activo central', 'El significado activo central: poner, colocar o establecer algo en posición, incluyendo el sentido legal especializado de emitir o promulgar un decreto. Esdras 5:3 pregunta ''¿Quién os dio decreto para edificar?'' y Esdras 6:1 registra la orden de Darío de realizar una búsqueda. La expresión שִׂים טְעֵם (''emitir decreto'') concentra la fuerza administrativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139284, 'spa', 'El Hitpael medio-pasivo, que expresa el proceso de ser colocado o establecido co', 'El Hitpael medio-pasivo, que expresa el proceso de ser colocado o establecido con matiz reflexivo. En Daniel 2:5, la palabra del rey ''es emitida'' (irrevocablemente establecida), y en Esdras 5:8, la obra ''se está realizando'' (literalmente ''siendo colocada/llevada a cabo''). Esta conjugación añade énfasis procesal — algo está en proceso de ser establecido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139290, 'spa', 'Un uso en Qal con objeto personal', 'Un uso en Qal con objeto personal: designar o constituir a alguien en un cargo. Esdras 5:14 registra que Ciro ''designó'' a Sesbasar como gobernador. La metáfora física de ''colocar'' a alguien en un lugar se extiende a la investidura formal en un oficio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139296, 'spa', 'Ciudad de Sunem', 'Los tres usos abarcan la lista de territorio tribal (Josué 19:18), el campamento militar filisteo (1 Samuel 28:4) y el lugar del ministerio de Eliseo (2 Reyes 4:8). El español ''Sunem'' y las versiones de varios idiomas transliteran consistentemente. La estabilidad geográfica es notable: desde la asignación en la época de la conquista hasta el reinado de Saúl y luego hasta el tiempo de Eliseo, Sunem permanece como un sitio reconocido. Su proximidad a Jezreel la convirtió en ubicación estratégica a través de múltiples períodos históricos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139297, 'spa', 'La sunamita', 'Adjetivo gentilicio femenino que identifica a una mujer de Sunem. Designa a dos mujeres distintas: Abisag la sunamita (1 R 1:3, 15; 2:17, 21, 22), la joven que atendia al anciano David y cuya mano se volvio premio politico, y la anonima mujer acaudalada (2 R 4:12, 25, 36) que hospedaba a Eliseo y presencio la resurreccion de su hijo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139299, 'spa', 'Clamar por ayuda', 'Clamar por ayuda. Clamar urgentemente por ayuda o rescate, típicamente en oración dirigida a Dios durante la angustia o el sufrimiento. El salmista clama y es escuchado (Sal 18:7; 30:3), pero el mismo verbo también expresa angustia sin respuesta (Job 19:7; 30:20; Hab 1:2; Lam 3:8). Jonás 2:3 lo usa desde el vientre del pez. Todas las apariciones convergen en un único sentido de clamor vocal y desesperado dirigido hacia el socorro divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139322, 'spa', 'Clamor de auxilio', 'Clamor de auxilio o grito de angustia dirigido a Dios, que expresa una súplica desesperada en tiempos de sufrimiento u opresión. Aparece en la narrativa del éxodo donde el gemido colectivo de Israel alcanza a Dios (Ex 2:23), en la acción de gracias real donde David recuerda que su clamor entró en los oídos divinos (2 S 22:7; Sal 18:6), y a lo largo de lamentos individuales (Sal 34:15; 39:13; 40:2; 72:12; 88:3; 102:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139328, 'spa', 'Zorro, chacal (cánido salvaje)', 'Pequeño cánido salvaje que abarca tanto al zorro (Vulpes vulpes) como al chacal (Canis aureus), ya que el hebreo bíblico no los distingue léxicamente. El gran número que Sansón capturó (Jue 15:4) sugiere chacales, más sociables, mientras que las «zorras pequeñas» de Cnt 2:15 evocan al zorro menor que saquea viñedos. Los falsos profetas son comparados con zorros entre ruinas (Ez 13:4), y la Sion desolada es recorrida por estos animales (Lm 5:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139335, 'spa', 'Guardian apostado en una puerta que controla quien entra y quien sale', 'Guardian apostado en una puerta que controla quien entra y quien sale. En su uso principal a lo largo de Cronicas, Esdras y Nehemias, se refiere a los porteros leviticos del Templo, un oficio consagrado y hereditario de considerable dignidad. El rol abarcaba la custodia de los umbrales (1 Cr 9:22), la procesion del Arca (1 Cr 15:23-24) y la puerta de la ciudad en tiempo de guerra (2 Re 7:10-11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139349, 'spa', 'Aplastar, herir', 'Aplastar, quebrantar o golpear con fuerza causando lesión. Se destaca en el doble uso de Génesis 3:15: la serpiente herirá el talón humano mientras la humanidad aplastará la cabeza de la serpiente, texto fundacional para entender el conflicto entre el bien y el mal. Job 9:17 lo emplea para describir el poder aplastante de Dios. Las traducciones multilingües (me-aplasta, écraser) confirman el sentido de fuerza destructiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139352, 'spa', 'El cuerno de carnero como instrumento de señal, que abarca la guerra (Jue 7', 'El cuerno de carnero como instrumento de señal, que abarca la guerra (Jue 7:8, 16), la teofanía (Éx 19:16; 20:18), la asamblea religiosa (Lv 25:9; Jl 2:1) y el anuncio profético (Is 27:13; 58:1). Este es el sentido dominante en 69 de las 72 ocurrencias. Las traducciones varían de modo revelador: el alemán Posaune enfatiza el sonido, el español cuerno el material, mientras que el francés trompette y muchos otros idiomas se enfocan en la función instrumental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139364, 'spa', 'El cuerno animal como objeto material, destacando su naturaleza de cuerno más qu', 'El cuerno animal como objeto material, destacando su naturaleza de cuerno más que su función de señalización. Atestiguado en 1 Cr 15:28, 2 Cr 15:14 y Sal 98:6, donde el shofar aparece junto a trompetas y címbalos en listados orquestales. Varias traducciones africanas y asiáticas usan palabras genéricas para «cuerno» (suajili pembe, árabe qurūn) en vez de términos específicos de instrumento, confirmando el enfoque en el objeto físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139369, 'spa', 'Regar o desbordar abundantemente', 'Los tres usos involucran a Dios regando abundantemente la tierra (Salmo 65:9) y cubas desbordando de vino y aceite (Joel 2:24, 3:13). El español usa ''regar'' (irrigar) y ''rebosar'' (desbordar), capturando tanto la irrigación como el desbordamiento. El contexto del Salmo es el cuidado de Dios por la creación, mientras que el doble uso en Joel aparece en promesa de restauración (2:24) y juicio de cosecha de naciones (3:13), mostrando que la abundancia puede significar tanto bendición como juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139370, 'spa', 'Calle o plaza', 'La calle o plaza pública de una ciudad, el espacio abierto donde la gente camina, se congrega y realiza su vida cotidiana. Proverbios 7:8 sitúa la escena de la tentación en la calle. Eclesiastés evoca los sonidos que se apagan con la vejez. Cantares 3:2 muestra la búsqueda urgente de la novia por las calles. Es el escenario de la visibilidad pública, el comercio y los encuentros fortuitos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139371, 'spa', 'Pierna, muslo (parte del cuerpo)', 'Pierna, muslo (parte del cuerpo). La pierna o muslo físico de una persona o animal. En contextos humanos se refiere a la pantorrilla o parte inferior de la pierna, distinta del muslo propiamente (Jue 15:8; Sal 147:10; Cant 5:15). En la legislación sacrificial designa la pata trasera superior dada a los sacerdotes como su porción (Éx 29:22, 27; Lev 7:32-34; 1 Sam 9:24). El español distingue útilmente ''pierna'' (miembro humano) de ''muslo'' (pieza del sacrificio), reflejando la división semántica del término hebreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139383, 'spa', 'Contemplar, ver, mirar', 'Contemplar, ver, mirar. Contemplar, observar, percibir visualmente con atención sostenida o meditación. Este sentido primario abarca trece apariciones, desde la visión profética de Balaam (''Lo contemplo desde lejos'', Núm 24:17), el lamento existencial de Job de que el ojo de Dios ya no lo verá (Job 7:8; 20:9), y la invitación del amado a mirar desde las cumbres del Líbano (Cant 4:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139386, 'spa', 'Cantar', 'Cantar. Cantar o entonar — un sentido raro y debatido atestiguado en Job 33:27, donde Elihú describe a una persona restaurada que ''canta ante otros'' en confesión. Puede reflejar una raíz homónima distinta relacionada con shir (''cantar'') en lugar del verbo visual. Algunas interpretaciones tradicionales apoyan la lectura vocal, aunque otros enmiendan el texto o reinterpretan el verbo como ''mirar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139388, 'spa', 'Acechar, espiar', 'Acechar, espiar. Observar con intención hostil o furtiva — acechar, espiar a alguien como un depredador que vigila a su presa. Dos apariciones cambian la valencia del verbo de contemplación a amenaza: en Jeremías 5:26, hombres impíos ''acechan'' como cazadores que tienden trampas, y en Oseas 13:7, Dios advierte ''como un leopardo acecharé junto al camino''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139398, 'spa', 'Muro o pared', 'Las tres ocurrencias son todas poéticas: las ramas fructíferas de José sobre un muro (Génesis 49:22) y el estribillo del salmo sobre saltar muros (2 Samuel 22:30 = Salmo 18:29). El español ''muro'' y el francés ''muraille'' aparecen. El texto de Génesis es discutido—algunos ven ''muro'' como parte de la imagen de bendición, otros proponen enmiendas. El uso del salmo claramente denota muros militares escalados con capacitación divina, mientras que Génesis puede usar la imagen del muro como límite que las bendiciones de José traspasan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139400, 'spa', 'Murallas de ciudad', 'Murallas de ciudad (término arameo usado en Esdras 4:12-16), específicamente las murallas de Jerusalén que los exiliados retornados estaban reconstruyendo. Las cartas al rey persa se centran obsesivamente en estas murallas como símbolo de posible rebelión y pérdida de ingresos. Las murallas representaban autonomía política y el derecho de una ciudad a existir en sus propios términos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (139401, 'spa', 'Shur', 'Shur, region geografica en la frontera oriental de Egipto y el borde suroeste de Canaan. La transliteracion se mantiene uniforme en las distintas lenguas, reflejando su condicion de nombre propio fijo. Funciona tanto como punto de referencia direccional (''el camino de Shur'', Gen 16:7) como designacion de un desierto (''desierto de Shur'', Exod 15:22), marcando el espacio liminal entre Egipto y la tierra prometida.');